import test from 'node:test';import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import {createRun,update,nova} from '../src/combat.js';import {AUDIO_FILES} from '../src/audio-manifest.js';import {ASSETS} from '../src/content.js';import {DIFFICULTIES} from '../src/difficulty.js';import {load,save,SAVE_KEY} from '../src/storage.js';
import {createEnemy,bossPattern,spawnWaves,updateEnemies} from '../src/enemies.js';
import {setBounds} from '../src/combat.js';
import {createSession} from '../src/session.js';
import {createNavigation} from '../src/navigation.js';
import {createGarage} from '../src/garage.js';
import {SYSTEMS,PREREQUISITES,INITIAL_DESTINATIONS} from '../src/galaxy/catalog.js';
import {createInitialProgress,evaluateCondition,destinationAccess,listDestinations,advanceProgress} from '../src/galaxy/unlocks.js';
import {PROGRESS_KEY,decodeProgress,createProgressStore} from '../src/progression/storage.js';
import {createGalaxyCamera,layoutSystems} from '../src/galaxy/camera.js';
test('Release : 21 graphismes, 39 WAV et leurs empreintes',async()=>{assert.equal(Object.keys(ASSETS).length,21);for(const asset of Object.values(ASSETS))await readFile(new URL('../'+asset,import.meta.url));const manifest=JSON.parse(await readFile(new URL('../assets/audio/provenance.json',import.meta.url)));assert.equal(Object.values(AUDIO_FILES).flat().length,39);for(const audio of manifest.variants){const bytes=await readFile(new URL('../'+audio.file,import.meta.url));assert.equal(bytes.toString('ascii',0,4),'RIFF');assert.equal(createHash('sha256').update(bytes).digest('hex'),audio.sha256);}});
test('Release : chaque difficulté conserve NOVA à zéro et le budget de projectiles',()=>{for(const difficulty of Object.keys(DIFFICULTIES)){const s=createRun({ship:'bastion',weapon:'missile',drone:'alpha',difficulty});assert.equal(s.novaCharge,0);assert.equal(nova(s),false);for(let i=0;i<20*120;i++)update(s,1/120);assert.ok(s.hostile.length<=100);assert.ok(s.bullets.length<=160);}});
test('Release : stockage isolé, erreurs de stockage tolérées',()=>{const calls=[],store={getItem(k){calls.push(k);return null;},setItem(k){calls.push(k);}};save(store,load(store));assert.deepEqual(calls,[SAVE_KEY,SAVE_KEY]);assert.equal(SAVE_KEY,'nv2_save_v1');assert.equal(save(null,{}),false);});
test('2.2 : pression progressive sans augmentation des effectifs ni des points de vie',()=>{
 for(const difficulty of ['easy','normal','hard']){const s=createRun({ship:'revenant',weapon:'flux',drone:'none',difficulty});s.t=34;spawnWaves(s);assert.equal(s.enemies.length,18);assert.equal(s.enemies.filter(e=>e.type==='fighter').length,9);assert.equal(s.enemies.filter(e=>e.type==='interceptor').length,6);assert.equal(s.enemies.filter(e=>e.type==='heavy').length,3);s.t=35;spawnWaves(s);assert.equal(s.bossSpawned,difficulty!=='easy');assert.equal(s.hp,100);if(s.bossSpawned)assert.equal(s.enemies.find(e=>e.boss).hp,360);}
});
test('2.2 : trois phases, alternance ciblage/barrages, cadence croissante',()=>{
 assert.deepEqual([...new Set(Array.from({length:10},(_,i)=>bossPattern(1,i)))],['fan']);
 for(const phase of [2,3])assert.deepEqual(new Set(Array.from({length:10},(_,i)=>bossPattern(phase,i))),new Set(['fan','split','columns']));
 for(const difficulty of ['normal','hard']){const waits=[];for(const phase of [1,2,3]){const s=createRun({ship:'revenant',weapon:'flux',drone:'none',difficulty});s.y=650;const e=createEnemy(s,'spectra',{age:4,y:145,hp:[360,200,80][phase-1],phase,cooldown:0});s.enemies.push(e);for(let i=0;i<300&&!s.stats.volleys;i++)updateEnemies(s,1/120);assert.equal(s.stats.volleys,1);waits.push(e.cooldown);assert.ok(s.hostile.every(b=>b.telegraphed&&b.arm>=.12));}assert.ok(waits[0]>waits[1]&&waits[1]>waits[2]);}
});
test('2.2 : cible figée, avertissement majeur et aucune création au contact',()=>{
 for(const difficulty of ['easy','normal','hard']){const s=createRun({ship:'bastion',weapon:'flux',drone:'none',difficulty});s.y=650;const e=createEnemy(s,'spectra',{age:4,y:145,cooldown:0});s.enemies.push(e);updateEnemies(s,1/120);const w=structuredClone(e.warning);assert.ok(w.duration>=.65);s.x=40;updateEnemies(s,1/120);assert.equal(e.warning.angle,w.angle);assert.equal(e.warning.aimX,w.aimX);s.x=e.x;s.y=e.y+e.r;for(let i=0;i<180;i++)updateEnemies(s,1/120);assert.equal(s.hostile.length,0);}
});
test('2.2 : déplacements variés, formations espacées et transitions du boss continues',()=>{
 const s=createRun({ship:'bastion',weapon:'flux',drone:'none',difficulty:'normal'});s.t=1;spawnWaves(s);updateEnemies(s,1/120);assert.equal(s.enemies[1].x-s.enemies[0].x,68);const e=createEnemy(s,'spectra',{age:8,y:145,cooldown:1000});s.enemies=[e];for(const hp of [360,200,80]){e.hp=hp;const x=e.x;updateEnemies(s,1/120);assert.ok(Math.abs(e.x-x)<=145/120+1e-9);}const directions=new Set();const f=createEnemy(s,'fighter',{age:4,group:0,slot:0,center:240,x:240,y:200,cooldown:1000});s.enemies=[f];for(let i=0;i<300;i++){const x=f.x;updateEnemies(s,1/120);directions.add(Math.sign(f.x-x));}assert.ok(directions.has(-1)&&directions.has(1));
});
test('2.2 : le dernier lourd peut terminer son annonce avant SPECTRA',()=>{const s=createRun({ship:'bastion',weapon:'flux',drone:'none',difficulty:'normal'});s.y=650;s.waveIndex=8;s.t=29.5;spawnWaves(s);const heavy=s.enemies[0];for(let i=0;i<5.45*120;i++){s.t+=1/120;spawnWaves(s);updateEnemies(s,1/120);}assert.equal(s.bossSpawned,false);assert.ok(s.hostile.some(b=>b.source===heavy.id));});
test('2.2 : une route sans dégâts pour chaque attaque majeure, format, difficulté et châssis',()=>{
 // Recherche discrète de routes avec 150 ms de réaction après le signal lumineux.
 // Cas isolés, sans invulnérabilité : ceci ne prouve pas tous les chevauchements possibles.
 for(const [width,height] of [[1152,720],[480,1066.667],[480,1038.769],[909,420]])for(const ship of ['revenant','wisp','bastion'])for(const difficulty of ['easy','normal','hard'])for(const phase of [1,2,3])for(const index of phase===1?[0]:[0,1,2]){
  let escaped=false;
  for(const dx of [-1,1,0]){const s=createRun({ship,weapon:'flux',drone:'none',difficulty});setBounds(s,width,height);s.waveIndex=9;s.bossSpawned=true;s.shot=1000;s.x=width/2;s.y=height*.85;const e=createEnemy(s,'spectra',{age:4,y:145,hp:[360,200,80][phase-1],phase,cooldown:0,attackIndex:index});s.enemies.push(e);let visibleAt=null;
   for(let i=0;i<6*120;i++){if(e.warning&&(difficulty==='easy'||e.warning.time<=.3)&&visibleAt===null)visibleAt=s.t;if(s.stats.volleys)e.cooldown=1000;update(s,1/120,{dx:visibleAt!==null&&s.t-visibleAt>=.15?dx:0});}if(s.stats.volleys===1&&s.stats.damageTaken===0){escaped=true;break;}
  }assert.ok(escaped,`${width}x${height} ${ship} ${difficulty} phase${phase} index${index}`);
 }
});

// Lot 3A étape 1 : contrats de navigation et cycle de vie, sans changer le moteur.
const deferred=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return {promise,resolve,reject};};
const loadout={ship:'revenant',weapon:'flux',drone:'none',difficulty:'normal'};
test('Navigation : deux écrans, nettoyage/entrée uniques et transitions non réentrantes',()=>{
 const calls=[];let nav;nav=createNavigation({leave:(from,to)=>{calls.push(['leave',from,to]);assert.equal(nav.show('menu'),false);},enter:(to,from)=>calls.push(['enter',to,from])});
 assert.equal(nav.screen,'menu');assert.equal(nav.show('combat'),true);assert.equal(nav.show('combat'),false);assert.equal(nav.show('menu'),true);assert.equal(calls.length,4);assert.throws(()=>nav.show('unknown'),RangeError);assert.equal(nav.screen,'menu');
});
test('Session : double départ refusé, configuration figée avant attente',async()=>{
 const s=createSession(),gate=deferred(),choice={...loadout};const first=s.start(choice,()=>gate.promise);choice.ship='bastion';assert.equal(s.launching,true);assert.equal(await s.start(loadout),null);gate.resolve();const run=await first;assert.equal(run.loadout.ship,'revenant');assert.equal(run.novaCharge,0);assert.equal(s.launching,false);assert.equal(await s.start(loadout),null);
});
test('Session : abandon pendant préparation invalide définitivement le départ',async()=>{
 const s=createSession(),gate=deferred();let current;const pending=s.start(loadout,check=>{current=check;return gate.promise;});s.abandon();assert.equal(current(),false);gate.resolve();assert.equal(await pending,null);assert.equal(s.run,null);assert.equal(s.active(true,true),false);
});
test('Session : une ancienne attente ne peut annuler ou remplacer le nouveau départ',async()=>{
 const s=createSession(),old=deferred(),fresh=deferred(),a=s.start(loadout,()=>old.promise);s.cancelStart();const b=s.start({...loadout,ship:'bastion'},()=>fresh.promise);old.resolve();assert.equal(await a,null);assert.equal(s.launching,true);fresh.resolve();assert.equal((await b).spec.hp,155);assert.equal(s.launching,false);
});
test('Session : échec de préparation libère le verrou ; rejet obsolète sans effet',async()=>{
 const s=createSession();await assert.rejects(s.start(loadout,async()=>{throw Error('audio');}),/audio/);assert.equal(s.launching,false);assert.equal(s.run,null);const gate=deferred(),pending=s.start(loadout,()=>gate.promise);s.cancelStart();gate.reject(Error('obsolete'));assert.equal(await pending,null);assert.ok(await s.start(loadout));
});
test('Session : écran caché, pause ou perte de focus interdisent tout pas de simulation',async()=>{
 const s=createSession(),run=await s.start(loadout);s.step(1/120,{dx:1},true,true);assert.ok(run.t>0);const frozen=JSON.stringify(run);
 for(const [visible,foreground] of [[false,true],[true,false],[false,false]])s.step(1/120,{dx:1},visible,foreground);assert.equal(JSON.stringify(run),frozen);s.pause();for(let i=0;i<1200;i++)s.step(1/120,{dx:1},true,true);assert.equal(JSON.stringify(run),frozen);s.resume();s.step(1/120,{},true,true);assert.ok(run.t>1/120);
});
test('Session : résultat terminal une seule fois, pause/focus ne réarment pas son écriture',async()=>{
 const s=createSession(),run=await s.start(loadout);assert.equal(s.takeResult(),null);run.score=3900;run.over=true;run.victory=true;assert.deepEqual(s.takeResult(),{score:3900,victory:true});s.pause();s.resume();s.cancelStart();assert.equal(s.takeResult(),null);assert.equal(s.active(true,true),false);const before=JSON.stringify(run);s.step(1/120,{},true,true);assert.equal(JSON.stringify(run),before);
});
test('Session : victoire ou défaite puis rejouer créent un vol neuf avec NOVA vide',async()=>{
 for(const victory of [true,false]){const s=createSession(),run=await s.start(loadout);run.over=true;run.victory=victory;run.novaCharge=100;assert.equal(s.takeResult().victory,victory);const next=await s.start(loadout);assert.notEqual(next,run);assert.equal(next.hp,100);assert.equal(next.novaCharge,0);assert.equal(next.over,false);assert.equal(s.takeResult(),null);s.abandon();assert.equal(s.run,null);assert.ok(await s.start(loadout));}
});
test('Garage : lecture sans écriture, profil V1, crédits et choix conservés',()=>{
 const initial={version:1,ship:'bastion',weapon:'missile',drone:'beta',credits:2468,best:13579},calls=[];let raw=JSON.stringify(initial);const g=createGarage({getItem:k=>{assert.equal(k,SAVE_KEY);return raw;},setItem:(k,v)=>{calls.push(k);raw=v;}});assert.equal(calls.length,0);assert.deepEqual(g.profile,initial);const copy=g.profile;copy.credits=0;assert.equal(g.profile.credits,2468);assert.equal(g.select('ship','wisp'),true);assert.equal(g.select('credits',500),false);assert.equal(g.select('ship','__proto__'),false);assert.equal(calls.length,1);assert.equal(JSON.parse(raw).credits,2468);assert.equal(JSON.parse(raw).version,1);
});
test('Résultat : une seule écriture, seul le record peut augmenter sans récompense',async()=>{
 let writes=0,raw=JSON.stringify({version:1,...loadout,credits:876,best:100});const garage=createGarage({getItem:()=>raw,setItem:(k,v)=>{assert.equal(k,SAVE_KEY);writes++;raw=v;}}),s=createSession(),run=await s.start(loadout);run.over=true;run.score=300;
 for(let i=0;i<100;i++){const result=s.takeResult();if(result)garage.recordResult(result);}assert.equal(writes,1);assert.equal(garage.profile.best,300);assert.equal(garage.profile.credits,876);assert.deepEqual(Object.keys(JSON.parse(raw)).sort(),['version','ship','weapon','drone','credits','best'].sort());
});
test('Garage : stockage refusé signalé, choix conservé en mémoire',()=>{let errors=0;const g=createGarage(null,()=>errors++);assert.equal(g.select('drone','alpha'),true);assert.equal(g.profile.drone,'alpha');assert.equal(errors,1);});
test('Session : 81 vols de 90 s identiques au moteur direct, trois difficultés/châssis/armes/drones',async()=>{
 for(const difficulty of ['easy','normal','hard'])for(const ship of ['revenant','wisp','bastion'])for(const weapon of ['flux','impact','missile'])for(const drone of ['none','alpha','beta']){
  const choice={ship,weapon,drone,difficulty},session=createSession(),a=await session.start(choice),b=createRun(choice);a.hp=b.hp=100000;
  for(let i=0;i<90*120;i++){const input={target:{x:240+Math.sin(b.t*.7)*90,y:550}};session.step(1/120,input,true,true);update(b,1/120,input);}assert.deepEqual(a,b,JSON.stringify(choice));
 }
});

// Lot 3A étape 2 : progression isolée, sans mission ni récompense.
function progressMemory(initial=null){const values=new Map(initial?[...initial]:[]),writes=[],reads=[];return {values,writes,reads,getItem(k){reads.push(k);return values.get(k)??null;},setItem(k,v){writes.push(k);values.set(k,v);}};}
test('Galaxie : cinq ID stables, destinations visibles, aucune mission/planète fictive',()=>{assert.deepEqual(SYSTEMS.map(s=>s.id),['nexus','aurora','echo','nyx','front_spectra']);assert.equal(new Set(SYSTEMS.map(s=>s.id)).size,5);for(const s of SYSTEMS){assert.ok(s.name&&s.description&&s.sectorType);assert.equal(s.visible,true);assert.deepEqual(s.missionIds,s.id==='nexus'?['nexus_m01']:[]);assert.deepEqual(s.planetIds,[]);}assert.ok(Object.values(PREREQUISITES).every(p=>p.implemented===false));});
test('Galaxie : catalogue/règles gelés et modification d’une vue sans effet sur les accès',()=>{assert.throws(()=>{SYSTEMS[2].initialAccess=true;},TypeError);assert.throws(()=>{SYSTEMS[2].unlockCondition.conditions.length=0;},TypeError);const state=createInitialProgress(),view=listDestinations(state);view[2].access.accessible=true;assert.equal(destinationAccess('echo',state).accessible,false);});
test('Progression : Nexus/Aurora seuls accessibles ; trois verrous visibles',()=>{const state=createInitialProgress();assert.deepEqual(state,{version:1,unlockedDestinations:['nexus','aurora'],accomplishments:[]});assert.deepEqual(listDestinations(state).filter(s=>s.access.accessible).map(s=>s.id),INITIAL_DESTINATIONS);for(const id of ['echo','nyx','front_spectra'])assert.deepEqual([destinationAccess(id,state).visible,destinationAccess(id,state).accessible],[true,false]);assert.equal(destinationAccess('unknown',state).status,'unknown');});
test('Écho : campagne OU découverte secondaire, données artificielles pures',()=>{for(const id of ['campaign.echo_access','secondary.echo_discovery']){const state=advanceProgress(createInitialProgress(),[id]);assert.equal(destinationAccess('echo',state).accessible,true);assert.equal(destinationAccess('nyx',state).accessible,false);}assert.equal(evaluateCondition(SYSTEMS[2].unlockCondition,[]),false);});
test('Nyx : progression majeure OU reconnaissance, données artificielles pures',()=>{for(const id of ['campaign.nyx_major_progress','recon.nyx_access'])assert.equal(destinationAccess('nyx',advanceProgress(createInitialProgress(),[id])).accessible,true);});
test('Front SPECTRA : accomplissements majeurs ET conquête, sans seuil inventé',()=>{const ids=['spectra.major_accomplishments','conquest.spectra_operation'];for(const id of ids)assert.equal(destinationAccess('front_spectra',advanceProgress(createInitialProgress(),[id])).accessible,false);assert.equal(destinationAccess('front_spectra',advanceProgress(createInitialProgress(),ids)).accessible,true);});
test('Conditions : prérequis absent/inconnu, règle vide ou malformée jamais satisfaits',()=>{for(const rule of [null,{}, {op:'all',conditions:[]},{op:'any',conditions:[]},{op:'fact',id:'missing'},{op:'fact',id:['campaign.echo_access']}])assert.equal(evaluateCondition(rule,['campaign.echo_access']),false);assert.equal(evaluateCondition(SYSTEMS[2].unlockCondition,null),false);assert.equal(evaluateCondition({op:'all',conditions:[{op:'fact',id:'campaign.echo_access'},{op:'fact',id:'missing'}]},['campaign.echo_access','missing']),false);});
test('Progression pure : aucune mutation ni doublon, application idempotente',()=>{const original=createInitialProgress(),snapshot=structuredClone(original),once=advanceProgress(original,['campaign.echo_access','campaign.echo_access']),twice=advanceProgress(once,['campaign.echo_access']);assert.deepEqual(original,snapshot);assert.deepEqual(twice,once);assert.equal(once.accomplishments.length,1);assert.equal(once.unlockedDestinations.length,3);assert.throws(()=>advanceProgress(original,['unknown']),TypeError);assert.throws(()=>advanceProgress(original,[['campaign.echo_access']]),TypeError);});
test('Déblocage permanent : disparition du fait courant ou rotation ne reverrouille pas',()=>{const state=advanceProgress(createInitialProgress(),['secondary.echo_discovery']);state.accomplishments=[];const later=advanceProgress(state,[]);assert.equal(destinationAccess('echo',later).accessible,true);assert.equal(decodeProgress(JSON.stringify(later)).state.unlockedDestinations.includes('echo'),true);});
test('Stockage : consultation sans écriture, initialisation unique puis rechargement',()=>{const memory=progressMemory(),store=createProgressStore(memory);assert.equal(store.diagnostics.status,'absent');store.state;listDestinations(store.state);assert.equal(memory.writes.length,0);assert.equal(store.initialize(),true);assert.deepEqual(memory.writes,[PROGRESS_KEY]);for(let i=0;i<10;i++){store.initialize();store.state;createProgressStore(memory).initialize();}assert.equal(memory.writes.length,1);assert.deepEqual(createProgressStore(memory).state,createInitialProgress());});
test('Stockage : initialisation ne lit ni ne modifie profil/préférences, aucun bonus rétroactif',()=>{const legacy='{ "version":1,"best":9999999,"credits":9999999 }',prefs='{ "enabled":false,"volume":0,"difficulty":"hard" }',memory=progressMemory([['nv2_save_v1',legacy],['nv2_preferences_v1',prefs]]),store=createProgressStore(memory);store.initialize();assert.equal(memory.values.get('nv2_save_v1'),legacy);assert.equal(memory.values.get('nv2_preferences_v1'),prefs);assert.ok(memory.reads.every(k=>k===PROGRESS_KEY));assert.deepEqual(memory.writes,[PROGRESS_KEY]);assert.deepEqual(store.state.accomplishments,[]);assert.equal(destinationAccess('front_spectra',store.state).accessible,false);});
test('Stockage : état valide acquis rechargé, snapshots isolés, aucune écriture de consultation',()=>{const fixture=advanceProgress(createInitialProgress(),['campaign.echo_access','recon.nyx_access']),raw=JSON.stringify(fixture),memory=progressMemory([[PROGRESS_KEY,raw]]),store=createProgressStore(memory);assert.equal(store.initialize(),true);assert.deepEqual(store.state,fixture);const copy=store.state;copy.unlockedDestinations.length=0;assert.deepEqual(store.state,fixture);assert.equal(memory.writes.length,0);assert.equal(memory.values.get(PROGRESS_KEY),raw);});
test('Stockage : doublons valides dédupliqués en mémoire sans réécriture silencieuse',()=>{const raw=JSON.stringify({version:1,unlockedDestinations:['echo','echo','nexus'],accomplishments:['campaign.echo_access','campaign.echo_access']}),memory=progressMemory([[PROGRESS_KEY,raw]]),store=createProgressStore(memory);store.initialize();assert.equal(store.state.accomplishments.length,1);assert.equal(store.state.unlockedDestinations.filter(id=>id==='echo').length,1);assert.equal(memory.writes.length,0);assert.equal(memory.values.get(PROGRESS_KEY),raw);});
test('Stockage : JSON invalide conservé, repli mémoire et aucune écriture possible',()=>{for(const raw of ['{bad','null','[]','42','{"version":1,"unlockedDestinations":[]}']){const memory=progressMemory([[PROGRESS_KEY,raw]]),issues=[],store=createProgressStore(memory,{onIssue:code=>issues.push(code)});assert.equal(store.diagnostics.status,'corrupt');assert.equal(store.initialize(),false);assert.equal(store.flush(),false);assert.equal(store.recordValidatedAccomplishments(['campaign.echo_access']).changed,false);assert.deepEqual(store.state,createInitialProgress());assert.equal(store.preservedRaw,raw);assert.equal(memory.values.get(PROGRESS_KEY),raw);assert.deepEqual(memory.writes,[]);assert.deepEqual(issues,['corrupt']);}});
test('Stockage : version inconnue/future ou données futures préservées sans remplacement',()=>{for(const value of [{version:99,unlockedDestinations:['echo']},{version:0},{version:1,unlockedDestinations:['nexus','future_system'],accomplishments:[]},{version:1,unlockedDestinations:['nexus'],accomplishments:['future_fact']}]){const raw=JSON.stringify(value),memory=progressMemory([[PROGRESS_KEY,raw]]),store=createProgressStore(memory);assert.equal(store.diagnostics.status,'incompatible');assert.equal(store.initialize(),false);assert.equal(store.preservedRaw,raw);assert.equal(memory.values.get(PROGRESS_KEY),raw);assert.equal(memory.writes.length,0);}});
test('Stockage : inaccessible signalé et repli mémoire sans réinitialisation',()=>{for(const storage of [null,{getItem(){throw Error('blocked');},setItem(){throw Error('must not write');}}]){const issues=[],store=createProgressStore(storage,{onIssue:c=>issues.push(c)});assert.deepEqual(store.state,createInitialProgress());assert.equal(store.initialize(),false);assert.equal(store.diagnostics.readOnly,true);assert.deepEqual(issues,['unavailable']);}});
test('Stockage : écriture refusée signalée, tentative explicite récupérable sans perte',()=>{let denied=true,raw=null,writes=0;const issues=[],store=createProgressStore({getItem:()=>raw,setItem:(k,v)=>{writes++;if(denied)throw Error('quota');raw=v;}},{onIssue:c=>issues.push(c)});assert.equal(store.initialize(),false);assert.equal(store.diagnostics.dirty,true);assert.deepEqual(store.state,createInitialProgress());assert.deepEqual(issues,['write-failed']);denied=false;assert.equal(store.initialize(),true);assert.equal(writes,2);store.initialize();assert.equal(writes,2);assert.equal(store.diagnostics.issue,null);});
test('Stockage : divergence externe détectée avant écriture, sans prétendre fusionner les onglets',()=>{const memory=progressMemory(),store=createProgressStore(memory);memory.values.set(PROGRESS_KEY,'preserve external raw');assert.equal(store.initialize(),false);assert.equal(store.diagnostics.issue,'conflict');assert.equal(memory.values.get(PROGRESS_KEY),'preserve external raw');assert.equal(memory.writes.length,0);});
test('Production actuelle : aucun producteur disponible, tous les nouveaux accomplissements refusés',()=>{const memory=progressMemory(),store=createProgressStore(memory);store.initialize();for(const id of Object.keys(PREREQUISITES)){assert.equal(store.recordValidatedAccomplishments([id]).reason,'unavailable-prerequisite');}assert.equal(store.recordValidatedAccomplishments(['__proto__']).reason,'invalid-accomplishment');assert.equal(store.recordValidatedAccomplishments([['campaign.echo_access']]).reason,'invalid-accomplishment');assert.equal(store.recordValidatedAccomplishments([]).changed,false);assert.deepEqual(store.state,createInitialProgress());assert.deepEqual(memory.writes,[PROGRESS_KEY]);});

// Lot 3A étape 3 : caméra indépendante et troisième écran, règles de jeu inchangées.
test('Carte : ouverture explicite sur galaxie, transitions et état historique menu conservés',()=>{const calls=[],nav=createNavigation({initial:'galaxy',leave:(a,b)=>calls.push([a,b]),enter:to=>calls.push(to)});assert.equal(nav.screen,'galaxy');nav.show('menu');nav.show('combat');nav.show('galaxy');assert.equal(calls.length,6);assert.equal(createNavigation().screen,'menu');assert.throws(()=>createNavigation({initial:'unknown'}),RangeError);});
test('Carte : cinq positions issues du catalogue, transposition portrait sans donnée fictive',()=>{const wide=layoutSystems(SYSTEMS),tall=layoutSystems(SYSTEMS,true);assert.deepEqual(wide.map(p=>p.id),SYSTEMS.map(s=>s.id));for(let i=0;i<5;i++)assert.deepEqual([wide[i].x,wide[i].y],[tall[i].y,tall[i].x]);});
test('Caméra : cadrage initial des cinq destinations, cinq surfaces PC/mobile',()=>{for(const [w,h,portrait] of [[1058,615,false],[540,234,false],[496,204,false],[362,383,true],[332,345,true]]){const points=layoutSystems(SYSTEMS,portrait),c=createGalaxyCamera(points);c.resize(w,h);for(const p of points){const q=c.project(p);assert.ok(q.x>=60&&q.x<=w-60);assert.ok(q.y>=43&&q.y<=h-43);}assert.equal(c.state.zoom,1);}});
test('Caméra : zoom borné, ancrage sous le pointeur et valeurs invalides sans effet',()=>{const c=createGalaxyCamera(layoutSystems(SYSTEMS));c.resize(900,500);const before=c.state,anchor={x:before.center.x+20/before.scale,y:before.center.y+10/before.scale};c.zoomAt(1.5,470,260);const q=c.project(anchor);assert.ok(Math.abs(q.x-470)<1e-8&&Math.abs(q.y-260)<1e-8);c.zoomAt(100);assert.equal(c.state.zoom,3.5);c.zoomAt(.0001);assert.equal(c.state.zoom,1);const frozen=c.state;c.pan(NaN,0);c.zoomAt(Infinity);c.resize(0,0);assert.deepEqual(c.state,frozen);});
test('Caméra : déplacement extrême ne perd pas entièrement les systèmes',()=>{const points=layoutSystems(SYSTEMS),c=createGalaxyCamera(points);c.resize(496,204);c.zoomAt(3.5);for(const [x,y] of [[1e6,1e6],[-1e6,1e6],[1e6,-1e6],[-1e6,-1e6]]){c.pan(x,y);assert.ok(points.some(p=>{const q=c.project(p);return q.x>=24-1e-7&&q.x<=472+1e-7&&q.y>=24-1e-7&&q.y<=180+1e-7;}));}});
test('Caméra : recentrage exact, orientation conservant zoom et centre transposé',()=>{const c=createGalaxyCamera(layoutSystems(SYSTEMS));c.resize(900,500);const home=c.state;c.zoomAt(1.5);c.pan(25,15);const before=c.state;c.resize(340,620,layoutSystems(SYSTEMS,true),true);assert.equal(c.state.zoom,before.zoom);assert.ok(Math.abs(c.state.center.x-before.center.y)<1e-8);assert.ok(Math.abs(c.state.center.y-before.center.x)<1e-8);c.resize(900,500,layoutSystems(SYSTEMS),true);c.recenter();assert.deepEqual(c.state,home);});
test('Fiches : libellés courts du catalogue, producteurs toujours indisponibles',()=>{for(const fact of Object.values(PREREQUISITES)){assert.ok(fact.label&&fact.description);assert.equal(fact.implemented,false);}assert.equal(destinationAccess('front_spectra',createInitialProgress()).accessible,false);});
// Lot 3A étape 3B : cadrage responsive sans modifier les données métier.
test('3B : composition remplit les deux axes utiles, six formats et fiche PC',()=>{
 for(const [w,h,portrait] of [[1376,615,false],[1216,435,false],[1058,615,false],[1056,435,false],[816,234,false],[772,204,false],[816,142,false],[772,112,false],[362,625,true],[332,581,true],[362,401,true]]){
  const aspect=portrait?Math.max(1,h-100)/Math.max(1,w-140):Math.max(1,w-140)/Math.max(1,h-100),points=layoutSystems(SYSTEMS,portrait,aspect),c=createGalaxyCamera(points);c.resize(w,h);
  const projected=points.map(p=>c.project(p)),xs=projected.map(p=>p.x),ys=projected.map(p=>p.y);
  assert.ok(Math.max(...xs)-Math.min(...xs)>=Math.max(1,w-140)*.94);assert.ok(Math.max(...ys)-Math.min(...ys)>=Math.max(1,h-100)*.94);
  for(const q of projected){assert.ok(q.x>=69&&q.x<=w-69);assert.ok(q.y>=43&&q.y<=h-43);}
 }
});
test('3B : fermeture/resize au zoom initial recadre tous les systèmes',()=>{
 const c=createGalaxyCamera(layoutSystems(SYSTEMS));c.resize(1000,600);c.pan(300,100);c.resize(1250,600,layoutSystems(SYSTEMS,false,1110/500));assert.equal(c.state.zoom,1);for(const q of layoutSystems(SYSTEMS,false,1110/500).map(p=>c.project(p))){assert.ok(q.x>=69&&q.x<=1181);assert.ok(q.y>=43&&q.y<=557);}
});
test('3B : resize avec zoom préserve la région relative et le recentrage',()=>{
 const a=layoutSystems(SYSTEMS,false,2),b=layoutSystems(SYSTEMS,false,3),c=createGalaxyCamera(a);c.resize(900,500);c.zoomAt(2);c.pan(12,15);const old=c.state;c.resize(1100,500,b);assert.equal(c.state.zoom,2);assert.ok(Math.abs((c.state.center.y-90)/(old.center.y-90)-2/3)<1e-9);c.recenter();assert.equal(c.state.zoom,1);
});
test('3B : calcul de présentation sans mutation du catalogue ni des verrous',()=>{const before=JSON.stringify(SYSTEMS);for(const ratio of [.2,1,5,NaN,-1,Infinity])layoutSystems(SYSTEMS,false,ratio);assert.equal(JSON.stringify(SYSTEMS),before);assert.deepEqual(listDestinations(createInitialProgress()).filter(s=>s.access.accessible).map(s=>s.id),['nexus','aurora']);});

