// Nexus M01 lot 1 : fondations, résultats uniquement dans des stockages isolés.
import {MISSIONS,missionById,missionsForSystem} from '../src/campaign/catalog.js';
import {initialMissionRecord,missionRecord,systemCampaignProgress,applyCampaignVictory} from '../src/campaign/progression.js';
const campaignWin=(difficulty='normal',stars=2)=>({missionId:'nexus_m01',victory:true,difficulty,stars});
test('Nexus : M01 disponible, trois difficultés, Mission 2 à venir',()=>{assert.equal(MISSIONS.length,1);const m=missionById('nexus_m01');assert.equal(m.systemId,'nexus');assert.equal(m.name,'Première Alerte');assert.equal(m.type,'defense');assert.equal(m.order,1);assert.equal(m.status,'available');assert.equal(m.playable,true);assert.deepEqual(m.difficulties,['easy','normal','hard']);assert.deepEqual(SYSTEMS[0].missionIds,missionsForSystem('nexus').map(m=>m.id));assert.equal(missionById('nexus_m02'),null);assert.throws(()=>{m.playable=true},TypeError);});
test('Campagne absente : records zéro dérivés, aucune migration ou écriture de consultation',()=>{const memory=progressMemory([[PROGRESS_KEY,JSON.stringify(createInitialProgress())]]),store=createProgressStore(memory),before=store.preservedRaw;store.initialize();assert.deepEqual(missionRecord(store.state,'nexus_m01'),{completed:false,bestStars:{easy:0,normal:0,hard:0}});assert.deepEqual(systemCampaignProgress(store.state,'nexus'),{completed:0,total:5});assert.equal(store.state.campaign,undefined);assert.equal(store.preservedRaw,before);assert.deepEqual(memory.writes,[]);});
test('Campagne : première victoire isolée persistée et rechargée, sans toucher aux anciennes clés',()=>{const memory=progressMemory([['nv2_save_v1','KEEP PROFILE'],['nv2_preferences_v1','KEEP PREFS']]),store=createProgressStore(memory);store.initialize();memory.writes.length=0;assert.deepEqual(store.recordMissionVictory(campaignWin()),{changed:true,persisted:true,reason:null});assert.deepEqual(memory.writes,[PROGRESS_KEY]);assert.deepEqual(missionRecord(createProgressStore(memory).state,'nexus_m01'),{completed:true,bestStars:{easy:0,normal:2,hard:0}});assert.equal(memory.values.get('nv2_save_v1'),'KEEP PROFILE');assert.equal(memory.values.get('nv2_preferences_v1'),'KEEP PREFS');});
test('Campagne : amélioration, doublon et record inférieur, aucune écriture redondante',()=>{const memory=progressMemory(),store=createProgressStore(memory);store.initialize();store.recordMissionVictory(campaignWin('easy',1));store.recordMissionVictory(campaignWin('easy',3));const count=memory.writes.length,raw=memory.values.get(PROGRESS_KEY);for(const stars of [3,2,1])assert.deepEqual(store.recordMissionVictory(campaignWin('easy',stars)),{changed:false,persisted:true,reason:null});assert.equal(memory.writes.length,count);assert.equal(memory.values.get(PROGRESS_KEY),raw);assert.equal(missionRecord(store.state,'nexus_m01').bestStars.easy,3);});
test('Campagne : trois difficultés indépendantes, une mission comptée une fois, neuf étoiles possibles',()=>{const memory=progressMemory(),store=createProgressStore(memory);for(const difficulty of ['easy','normal','hard']){store.recordMissionVictory(campaignWin(difficulty,3));assert.deepEqual(systemCampaignProgress(store.state,'nexus'),{completed:1,total:5});}assert.deepEqual(missionRecord(store.state,'nexus_m01').bestStars,{easy:3,normal:3,hard:3});assert.equal(missionById('nexus_m02'),null);assert.ok(!Object.hasOwn(store.state.campaign.missions,'nexus_m02'));});
test('Campagne : maximum commutatif et idempotent, résultat pur sans mutation',()=>{const base=createInitialProgress();for(const a of [1,2,3])for(const b of [1,2,3]){const x=applyCampaignVictory(applyCampaignVictory(base,campaignWin('normal',a)).state,campaignWin('normal',b)).state,y=applyCampaignVictory(applyCampaignVictory(base,campaignWin('normal',b)).state,campaignWin('normal',a)).state;assert.deepEqual(x,y);assert.equal(missionRecord(x,'nexus_m01').bestStars.normal,Math.max(a,b));assert.equal(applyCampaignVictory(x,campaignWin('normal',a)).changed,false);}assert.equal(base.campaign,undefined);});
test('Campagne : défaite, abandon implicite et résultat invalide jamais enregistrés',()=>{const memory=progressMemory([[PROGRESS_KEY,JSON.stringify(createInitialProgress())]]),store=createProgressStore(memory);for(const result of [null,{}, {...campaignWin(),victory:false},{...campaignWin(),victory:undefined},{...campaignWin(),missionId:'nexus_m02'},{...campaignWin(),difficulty:'__proto__'},...[-1,0,4,1.5,NaN,'3'].map(stars=>({...campaignWin(),stars}))])assert.equal(store.recordMissionVictory(result).persisted,false);assert.deepEqual(memory.writes,[]);assert.equal(store.state.campaign,undefined);});
test('Campagne : accès galactiques et accomplissements conservés, aucun déblocage lié aux étoiles',()=>{const initial=advanceProgress(createInitialProgress(),['campaign.echo_access']),memory=progressMemory([[PROGRESS_KEY,JSON.stringify(initial)]]),store=createProgressStore(memory);store.recordMissionVictory(campaignWin());assert.deepEqual(store.state.unlockedDestinations,initial.unlockedDestinations);assert.deepEqual(store.state.accomplishments,initial.accomplishments);assert.equal(destinationAccess('nyx',store.state).accessible,false);assert.equal(destinationAccess('front_spectra',store.state).accessible,false);});
test('Compatibilité : extensions V1 inconnues préservées lors d’une victoire et d’un progrès galactique',()=>{const fixture={...createInitialProgress(),futureField:7,extension:{nested:['keep',42]},campaign:{version:1,missions:{future_mission:{opaque:'KEEP'}},extra:'KEEP CAMPAIGN'}},raw=JSON.stringify(fixture),memory=progressMemory([[PROGRESS_KEY,raw]]),store=createProgressStore(memory);assert.equal(store.diagnostics.readOnly,false);store.initialize();assert.equal(memory.writes.length,0);store.recordMissionVictory(campaignWin());let next=JSON.parse(memory.values.get(PROGRESS_KEY));assert.equal(next.futureField,7);assert.deepEqual(next.extension,fixture.extension);assert.deepEqual(next.campaign.missions.future_mission,fixture.campaign.missions.future_mission);assert.equal(next.campaign.extra,'KEEP CAMPAIGN');next=advanceProgress(next,['campaign.echo_access']);assert.equal(next.campaign.extra,'KEEP CAMPAIGN');assert.deepEqual(next.extension,fixture.extension);});
test('Compatibilité : extensions du record et des difficultés futures conservées',()=>{const fixture=applyCampaignVictory(createInitialProgress(),campaignWin('easy',1)).state;fixture.campaign.missions.nexus_m01.note='KEEP';fixture.campaign.missions.nexus_m01.bestStars.future=17;const memory=progressMemory([[PROGRESS_KEY,JSON.stringify(fixture)]]),store=createProgressStore(memory);store.recordMissionVictory(campaignWin('normal',2));const record=missionRecord(store.state,'nexus_m01');assert.equal(record.note,'KEEP');assert.equal(record.bestStars.future,17);});
test('Compatibilité : données campagne corrompues refusées sans réécriture',()=>{for(const campaign of [null,[],{version:1,missions:[]},{version:1,missions:{nexus_m01:{completed:false,bestStars:{easy:1,normal:0,hard:0}}}},{version:1,missions:{nexus_m01:{completed:true,bestStars:{easy:4,normal:0,hard:0}}}},{version:1,missions:{nexus_m01:{completed:true,bestStars:{easy:1,normal:0}}}}]){const raw=JSON.stringify({...createInitialProgress(),campaign}),memory=progressMemory([[PROGRESS_KEY,raw]]),store=createProgressStore(memory);assert.equal(store.diagnostics.status,'corrupt');assert.equal(store.initialize(),false);assert.equal(store.recordMissionVictory(campaignWin()).persisted,false);assert.equal(memory.values.get(PROGRESS_KEY),raw);assert.deepEqual(memory.writes,[]);}});
test('Compatibilité : version future de racine ou de campagne intacte et en lecture seule',()=>{for(const fixture of [{...createInitialProgress(),version:99},{...createInitialProgress(),campaign:{version:2,missions:{nexus_m01:{future:true}}}}]){const raw=JSON.stringify(fixture),memory=progressMemory([[PROGRESS_KEY,raw]]),store=createProgressStore(memory);assert.equal(store.diagnostics.status,'incompatible');assert.equal(store.recordMissionVictory(campaignWin()).persisted,false);assert.equal(memory.values.get(PROGRESS_KEY),raw);assert.deepEqual(memory.writes,[]);}});
test('Campagne : quota refusé signalé, amélioration en mémoire puis reprise idempotente',()=>{let denied=true,raw=JSON.stringify(createInitialProgress()),attempts=0;const issues=[],memory={getItem:()=>raw,setItem:(k,v)=>{attempts++;if(denied)throw Error('quota');raw=v}},store=createProgressStore(memory,{onIssue:c=>issues.push(c)});assert.deepEqual(store.recordMissionVictory(campaignWin('hard',3)),{changed:true,persisted:false,reason:'write-failed'});assert.deepEqual(issues,['write-failed']);assert.equal(store.diagnostics.dirty,true);assert.equal(missionRecord(store.state,'nexus_m01').bestStars.hard,3);denied=false;assert.deepEqual(store.recordMissionVictory(campaignWin('hard',1)),{changed:false,persisted:true,reason:null});assert.equal(attempts,2);assert.equal(missionRecord(createProgressStore(memory).state,'nexus_m01').bestStars.hard,3);store.recordMissionVictory(campaignWin('hard',3));assert.equal(attempts,2);});
test('Campagne : conflit externe n’écrase pas une sauvegarde concurrente',()=>{const memory=progressMemory([[PROGRESS_KEY,JSON.stringify(createInitialProgress())]]),store=createProgressStore(memory);memory.values.set(PROGRESS_KEY,'KEEP EXTERNAL');assert.equal(store.recordMissionVictory(campaignWin()).persisted,false);assert.equal(store.diagnostics.issue,'conflict');assert.equal(memory.values.get(PROGRESS_KEY),'KEEP EXTERNAL');assert.deepEqual(memory.writes,[]);});
test('Campagne : snapshots profonds isolés et aucune économie dans le schéma',()=>{const memory=progressMemory(),store=createProgressStore(memory);store.recordMissionVictory(campaignWin());const snapshot=store.state;snapshot.campaign.missions.nexus_m01.bestStars.normal=0;assert.equal(missionRecord(store.state,'nexus_m01').bestStars.normal,2);assert.deepEqual(Object.keys(store.state.campaign).sort(),['missions','version','weapons']);assert.deepEqual(Object.keys(store.state.campaign.missions.nexus_m01).sort(),['bestStars','completed']);assert.deepEqual(Object.keys(store.state).sort(),['accomplishments','campaign','unlockedDestinations','version']);assert.throws(()=>initialMissionRecord('missing'),TypeError);});
test('Campagne : un résultat valide idempotent efface une ancienne erreur de validation',()=>{const store=createProgressStore(progressMemory());store.recordMissionVictory(campaignWin());store.recordMissionVictory({...campaignWin(),victory:false});assert.equal(store.diagnostics.issue,'invalid-campaign-result');assert.deepEqual(store.recordMissionVictory(campaignWin()),{changed:false,persisted:true,reason:null});assert.equal(store.diagnostics.issue,null);});
test('Compatibilité : extension numérique non représentable conservée brute sans réécriture',()=>{const raw='{"version":1,"unlockedDestinations":["nexus","aurora"],"accomplishments":[],"opaque":1e999}',memory=progressMemory([[PROGRESS_KEY,raw]]),store=createProgressStore(memory);assert.equal(store.diagnostics.status,'incompatible');assert.equal(store.initialize(),false);assert.equal(store.recordMissionVictory(campaignWin()).persisted,false);assert.equal(memory.values.get(PROGRESS_KEY),raw);assert.deepEqual(memory.writes,[]);});

// Nexus M01 lot 2A : défense isolée, aucune mission complète ni écriture de victoire.
import {createNexusDefense} from '../src/defense/nexus.js';
import {BOMBERS,DEFENSE_COUNTS,DEFENSE_LIMIT} from '../src/defense/config.js';
import {createDefenseRun,addBomber,setDefenseBounds,updateDefenseRun,stopDefenseRun,createDefenseSession} from '../src/defense/simulation.js';
import {sweptShot} from '../src/defense/collisions.js';
import {bullet} from '../src/weapons.js';
function defenseFixture(ship='bastion',weapon='flux',drone='none',difficulty='normal'){const s=createDefenseRun({ship,weapon,drone,difficulty});setDefenseBounds(s,480,720);s.x=60;s.y=500;s.shot=999;s.droneShot=999;return s;}
function placeBomber(s,kind='light',progress=.99,rate=2.4){const e=addBomber(s,kind,.5);e.defenseBomber.progress=progress;e.defenseBomber.rate=rate;setDefenseBounds(s,s.width,s.height);return e;}
test('Défense : intégrité initiale, dégâts fixes, pas de réparation et nouvelle tentative',()=>{const d=createNexusDefense();assert.equal(d.state.integrity,100);d.register(1,'light');assert.equal(d.crossing(1),true);assert.equal(d.state.integrity,90);d.register(2,'heavy');d.crossing(2);assert.equal(d.state.integrity,70);d.resume();d.tick(5);assert.equal(d.state.integrity,70);assert.equal(d.repair,undefined);assert.equal(createNexusDefense().state.integrity,100);});
test('Défense : bombardiers valides uniquement, résolution unique et destruction avant limite',()=>{const d=createNexusDefense();for(const [id,kind] of [[0,'light'],[1,'fighter'],[2,'__proto__']])assert.equal(d.register(id,kind),false);assert.equal(d.crossing(99),false);d.register(1,'light');assert.equal(d.register(1,'heavy'),false);d.destroyed(1);assert.equal(d.crossing(1),false);d.register(2,'heavy');d.crossing(2);d.crossing(2);d.destroyed(2);assert.equal(d.state.integrity,80);});
test('Défense : zéro borné, destruction unique, aucun dégât après destruction ou fin',()=>{const d=createNexusDefense();for(let i=1;i<=7;i++){d.register(i,'heavy');d.crossing(i);}assert.equal(d.state.integrity,0);assert.equal(d.state.destroyed,true);assert.equal(d.state.activeBombers,0);assert.equal(d.takeEvents().filter(e=>e.type==='destroyed').length,1);assert.equal(d.crossing(1),false);d.end();assert.equal(d.register(8,'light'),false);assert.equal(d.crossing(8),false);assert.deepEqual(d.takeEvents(),[]);});
test('Défense : pause fige horloge, résolutions et alertes, reprise explicite',()=>{const d=createNexusDefense();d.register(1,'light');d.takeEvents();d.suspend();const frozen=d.state;d.tick(10);d.crossing(1);d.approach(1);assert.deepEqual(d.state,frozen);assert.deepEqual(d.takeEvents(),[]);d.resume();d.tick(.5);d.approach(1);d.approach(1);assert.equal(d.takeEvents().length,1);d.crossing(1);assert.equal(d.state.integrity,90);});
test('Bombardiers : vitesses et résistances dérivées, quantités provisoires et dégâts invariants',()=>{assert.ok(BOMBERS.light.speed>BOMBERS.heavy.speed);assert.ok(BOMBERS.heavy.hp>BOMBERS.light.hp);assert.deepEqual(DEFENSE_COUNTS,{easy:{light:4,heavy:1},normal:{light:6,heavy:2},hard:{light:8,heavy:3}});for(const difficulty of ['easy','normal','hard'])for(const drone of ['none','alpha','beta']){const s=defenseFixture('bastion','flux',drone,difficulty);placeBomber(s,'light',.999,50);updateDefenseRun(s,1/120);assert.equal(s.nexus.state.integrity,90);placeBomber(s,'heavy',.999,50);updateDefenseRun(s,1/120);assert.equal(s.nexus.state.integrity,70);}});
test('Balayage : impact continu de projectile, coin exact et trajectoire manquée',()=>{assert.ok(sweptShot({x:0,y:100},{x:0,y:-100},{x:0,y:0},{x:0,y:0},25)<.5);assert.equal(sweptShot({x:100,y:100},{x:100,y:-100},{x:0,y:0},{x:0,y:0},25),Infinity);assert.equal(sweptShot({x:29,y:36},{x:29,y:36},{x:0,y:0},{x:0,y:0},25),Infinity);});
test('Ordre : impact avant franchissement détruit sans dégâts, égalité ou après donne priorité à la limite',()=>{for(const [fraction,damage] of [[.25,0],[.5,10],[.75,10]]){const s=defenseFixture(),e=placeBomber(s),dt=1/120,movement=(s.height*DEFENSE_LIMIT+e.size)*e.defenseBomber.rate*dt;bullet(s,e.x,e.y+e.r+11+(movement+600*dt)*fraction,0,-600,'plasma',100);updateDefenseRun(s,dt);assert.equal(s.nexus.state.integrity,100-damage,`fraction ${fraction}`);assert.equal(s.enemies.length,0);assert.equal(s.nexus.state.activeBombers,0);assert.equal(s.stats.playerKills,damage?0:1);nova({...s,novaCharge:100});assert.equal(s.nexus.state.integrity,100-damage);}});
test('Ordre : projectile mort ou expiré avant impact ne peut intercepter',()=>{const s=defenseFixture(),e=placeBomber(s);bullet(s,e.x,e.y+100,0,-100,'plasma',100);s.bullets[0].life=.0001;updateDefenseRun(s,1/120);assert.equal(s.nexus.state.integrity,90);});
test('Franchissement : très grande vitesse et aucun double événement sur les étapes suivantes',()=>{const s=defenseFixture(),e=placeBomber(s,'heavy',0,1000);updateDefenseRun(s,1/120);assert.equal(s.nexus.state.integrity,80);for(let i=0;i<30;i++)updateDefenseRun(s,1/120);assert.equal(s.nexus.state.integrity,80);assert.equal(s.enemies.length,0);assert.equal(s.nexus.crossing(e.id),false);});
test('Redimensionnement : progression normalisée inchangée, aucune résolution pendant le changement',()=>{const s=defenseFixture(),e=placeBomber(s,'light',.98,.01);s.nexus.takeEvents();for(const [w,h] of [[480,1066],[1152,720],[909,420],[480,1038]]){setDefenseBounds(s,w,h);assert.equal(e.defenseBomber.progress,.98);assert.equal(s.nexus.state.integrity,100);assert.deepEqual(s.nexus.takeEvents(),[]);assert.ok(e.y<s.height*DEFENSE_LIMIT);}assert.equal(s.nexus.state.activeBombers,1);});
test('Interception réelle : trois vaisseaux, trois armes, trois drones, deux catégories et trois surfaces',()=>{let count=0;for(const [width,height] of [[1152,720],[480,1038],[480,1066]])for(const ship of ['revenant','wisp','bastion'])for(const weapon of ['flux','impact','missile'])for(const drone of ['none','alpha','beta'])for(const kind of ['light','heavy']){const s=createDefenseRun({ship,weapon,drone,difficulty:'normal'});setDefenseBounds(s,width,height);const e=addBomber(s,kind,.5);e.defenseBomber.progress=.3;setDefenseBounds(s,width,height);s.x=e.x;s.y=e.y+e.size/2+s.spec.size/2+15;for(let i=0;i<20*120&&s.enemies.length&&!s.over;i++)updateDefenseRun(s,1/120,{target:{x:e.x,y:e.y+e.size/2+s.spec.size/2+15}});assert.equal(s.nexus.state.integrity,100,`${ship}/${weapon}/${drone}/${kind}/${width}×${height}`);assert.equal(s.enemies.length,0);assert.ok(s.stats.playerKills+s.stats.droneKills===1);count++;}assert.equal(count,162);});
test('Drone Alpha : interception sans tir du pilote et charge NOVA existante',()=>{const s=createDefenseRun({ship:'revenant',weapon:'flux',drone:'alpha',difficulty:'normal'}),e=addBomber(s,'light',.5);e.defenseBomber.progress=.2;setDefenseBounds(s,480,720);s.x=e.x;s.y=e.y+140;s.shot=999;for(let i=0;i<10*120&&s.enemies.length;i++)updateDefenseRun(s,1/120,{target:{x:e.x,y:e.y+130}});assert.equal(s.stats.droneKills,1);assert.equal(s.nexus.state.integrity,100);assert.equal(s.novaCharge,12);});
test('NOVA : dégâts et coût inchangés, nettoyage hostile, aucune réparation de Nexus',()=>{const s=defenseFixture();placeBomber(s,'light',.999,100);updateDefenseRun(s,1/120);assert.equal(s.nexus.state.integrity,90);const e=placeBomber(s,'heavy',.6,.01);s.x=e.x;s.y=e.y+100;s.novaCharge=100;s.hostile=[{x:s.x,y:s.y,vx:0,vy:0,arm:1,life:3,r:5,damage:1}];assert.equal(nova(s),true);assert.equal(e.hp,14);assert.equal(s.hostile.length,0);assert.equal(s.novaCharge,0);assert.equal(s.nexus.state.integrity,90);const light=addBomber(s,'light',.5);light.defenseBomber.progress=.6;setDefenseBounds(s,480,720);s.novaCharge=100;nova(s);updateDefenseRun(s,1/120);assert.equal(s.nexus.state.integrity,90);assert.equal(s.novaCharge,0);});
test('Défense : destruction Nexus termine et nettoie tous les bombardiers sans victoire',()=>{const s=defenseFixture();for(let i=0;i<7;i++)placeBomber(s,'heavy',.999,100);updateDefenseRun(s,1/120);assert.equal(s.nexus.state.integrity,0);assert.equal(s.over,true);assert.equal(s.victory,false);assert.equal(s.enemies.length,0);assert.equal(s.nexus.state.activeBombers,0);assert.deepEqual(s.nexus.takeEvents(),[]);const before=JSON.stringify(s);updateDefenseRun(s,.1);assert.equal(JSON.stringify(s),before);});
test('Défense : session déjà terminée ou pilote détruit interdit tout nouveau dégât',()=>{for(const ended of [true,false]){const s=defenseFixture();placeBomber(s,'heavy',.999,100);if(ended)s.over=true;else s.hp=0;updateDefenseRun(s,.05);assert.equal(s.nexus.state.integrity,100);if(!ended)assert.equal(s.enemies.length,0);}});
test('Défense : pas long subdivisé, délai suspendu non accumulé et notifications bornées',()=>{const s=defenseFixture();for(let i=0;i<20;i++)placeBomber(s,'light',.99,1);updateDefenseRun(s,.1);assert.equal(s.nexus.state.integrity,0);assert.equal(s.over,true);const a=defenseFixture();placeBomber(a,'light',.95,.1);a.nexus.suspend();const before=JSON.stringify(a);updateDefenseRun(a,.2);assert.equal(JSON.stringify(a),before);a.nexus.resume();updateDefenseRun(a,.5);assert.equal(a.t,0);updateDefenseRun(a,1/120);assert.ok(a.t>0);});
test('Session technique : pause, visibilité, abandon, nettoyage et nouvelle tentative sans résultat',async()=>{const session=createDefenseSession(),s=await session.start(loadout);placeBomber(s,'light',.95,.1);session.pause();const frozen=JSON.stringify(s);for(let i=0;i<300;i++)session.step(1/120,{},true,true);assert.equal(JSON.stringify(s),frozen);session.resume();const running=JSON.stringify(s);session.step(.05,{},false,true);session.step(.05,{},true,false);assert.equal(JSON.stringify(s),running);session.step(1/120,{},true,true);assert.ok(s.t>0);session.abandon();assert.equal(session.run,null);assert.equal(s.enemies.length,0);assert.equal(s.nexus.state.activeBombers,0);assert.deepEqual(s.events,[]);assert.deepEqual(s.nexus.takeEvents(),[]);assert.equal(session.takeResult(),null);const next=await session.start(loadout);assert.equal(next.nexus.state.integrity,100);assert.equal(next.novaCharge,0);assert.equal(next.enemies.length,0);session.abandon();});
test('Session technique : même une fin artificielle ne produit aucun résultat de campagne',async()=>{const session=createDefenseSession(),s=await session.start(loadout);s.over=true;s.victory=true;assert.equal(session.takeResult(),null);assert.equal(missionById('nexus_m01').playable,true);assert.equal(missionById('nexus_m01').status,'available');session.abandon();});
test('Session technique : fin explicite sans dégât, sans événement résiduel et sans résultat',async()=>{const session=createDefenseSession(),s=await session.start(loadout);placeBomber(s,'heavy',.999,100);session.end();session.step(.1,{},true,true);assert.equal(s.nexus.state.integrity,100);assert.equal(s.over,true);assert.equal(s.victory,false);assert.equal(s.nexus.state.activeBombers,0);assert.deepEqual(s.nexus.takeEvents(),[]);assert.deepEqual(s.events,[]);assert.equal(session.takeResult(),null);assert.equal(s.enemies.length,0);});
test('Alertes défense : file bornée et événement de destruction conservé même après une rafale',()=>{const d=createNexusDefense();for(let i=1;i<=20;i++)d.register(i,'heavy');for(let i=1;i<=20;i++)d.approach(i);for(let i=1;i<=20;i++)d.crossing(i);const events=d.takeEvents();assert.ok(events.length<=32);assert.equal(events.filter(e=>e.type==='destroyed').length,1);assert.equal(d.state.integrity,0);});

// Lot 2B : contrôleur technique isolé, sans raccordement aux résultats persistants.
import {createNexusMissionRun,updateNexusMission,nexusMissionState,createNexusMissionSession} from '../src/campaign/nexus-m01.js';
import {BREAKER,M01_PLAN,M01_LIMITS,missionSchedule} from '../src/campaign/nexus-m01-config.js';
import {damageEnemy} from '../src/combat.js';
const m01Run=(difficulty='normal',ship='revenant')=>{const s=createNexusMissionRun({ship,weapon:'flux',drone:'none',difficulty});s.hp=10000;s.shot=10000;return s;};
function m01Steps(s,seconds,kill=false){for(let i=0;i<Math.ceil(seconds*120)&&!s.over;i++){if(kill)for(const e of s.enemies)damageEnemy(s,e,10000,'player');updateNexusMission(s,1/120);}}
function m01Until(s,predicate,seconds=180,kill=false){for(let i=0;i<seconds*120&&!predicate(s)&&!s.over;i++){if(kill)for(const e of s.enemies)damageEnemy(s,e,10000,'player');updateNexusMission(s,1/120);}assert.ok(predicate(s),JSON.stringify(nexusMissionState(s)));}
test('M01 2B : ordonnancement trois phases, sans menace résiduelle et sans résultat public',()=>{
 const s=m01Run();m01Until(s,s=>s.over,180,true);const m=nexusMissionState(s);
 assert.deepEqual(m.history.map(h=>h.phase),[1,2,3]);assert.ok(m.history.every(h=>h.remainingEnemies===0&&h.remainingHostile===0));assert.equal(m.history[0].nexus,100);assert.equal(m.outcome.reason,'objectives_met');assert.equal(m.breakerDestroyed,true);assert.equal(s.victory,false);assert.equal(s.ending,null);
});
test('M01 2B : effectifs exacts et répartition par difficulté, dégâts 10/20 conservés',()=>{
 for(const difficulty of ['easy','normal','hard']){const s=m01Run(difficulty);m01Until(s,s=>s.over,180,true);const m=nexusMissionState(s),expected=DEFENSE_COUNTS[difficulty];
  for(const kind of ['light','heavy']){assert.equal(m.resolved.filter(e=>e.kind===kind).length,expected[kind]);for(const phase of [2,3])assert.equal(m.resolved.filter(e=>e.kind===kind&&e.phase===phase).length,M01_PLAN[difficulty][phase-2][kind]);}
  assert.equal(m.resolved.filter(e=>e.kind==='fighter').length,12);assert.equal(m.resolved.filter(e=>e.kind==='breaker').length,1);assert.equal(m.breakerSpawned,true);assert.equal(BOMBERS.light.damage,10);assert.equal(BOMBERS.heavy.damage,20);
 }
});
test('M01 2B : phase 1 chasseurs uniquement, Nexus intacte, calendrier incomplet bloquant',()=>{
 const s=m01Run();m01Steps(s,2,true);assert.equal(nexusMissionState(s).phase,1);assert.equal(nexusMissionState(s).pending,1);assert.equal(s.nexus.state.integrity,100);assert.ok(s.enemies.every(e=>e.type==='fighter'&&!e.defenseBomber));m01Steps(s,4,true);assert.equal(nexusMissionState(s).phase,1);
});
test('M01 2B : des tirs hostiles résiduels bloquent réellement une transition',()=>{
 const s=m01Run();s.hostile.push({x:10,y:10,vx:0,vy:0,r:1,damage:0,life:30,arm:0});m01Steps(s,12,true);assert.equal(nexusMissionState(s).phase,1);assert.equal(nexusMissionState(s).active,0);assert.equal(nexusMissionState(s).pending,0);assert.equal(s.hostile.length,1);m01Steps(s,19,true);assert.equal(nexusMissionState(s).phase,2);
});
test('M01 2B : chronomètre seul insuffisant, Briseur vivant bloque la troisième phase',()=>{
 const s=m01Run();m01Until(s,s=>nexusMissionState(s).phase===3,100,true);m01Steps(s,100);const m=nexusMissionState(s);assert.equal(m.phase,3);assert.equal(m.breakerSpawned,true);assert.equal(m.breakerDestroyed,false);assert.equal(m.outcome,null);assert.ok(s.enemies.some(e=>e.breaker));
});
test('M01 2B : annonce puis une seule apparition, valeurs et salves historiques du Briseur',()=>{
 for(const difficulty of ['easy','normal','hard']){const s=m01Run(difficulty);m01Until(s,s=>nexusMissionState(s).phase===3,100,true);assert.ok(nexusMissionState(s).announcement);m01Steps(s,BREAKER.announcement-.05);assert.equal(s.enemies.some(e=>e.breaker),false);m01Steps(s,.1);const e=s.enemies.find(e=>e.breaker);assert.ok(e);assert.equal(e.hp,96);assert.equal(e.boss,false);assert.equal(e.type,'heavy');assert.equal(e.r,46.8);assert.equal(e.size,141.6);const integrity=s.nexus.state.integrity;
 m01Steps(s,8);const x=e.x;assert.ok(e.warning||s.stats.volleys>0);m01Steps(s,5);assert.notEqual(e.x,x);assert.ok(s.stats.volleys>0);assert.ok(s.hostile.every(b=>b.telegraphed&&b.source===e.id));assert.equal(s.nexus.state.integrity,integrity);
 damageEnemy(s,e,10000,'player');m01Steps(s,.1);assert.equal(s.ending,null);assert.equal(nexusMissionState(s).breakerDestroyed,true);m01Steps(s,1);assert.equal(s.enemies.filter(e=>e.breaker).length,0);
 }
});
test('M01 2B : Briseur détruit ne supprime pas les bombardiers ni leurs arrivées restantes',()=>{
 const s=m01Run();m01Until(s,s=>nexusMissionState(s).phase===3,100,true);m01Until(s,s=>s.enemies.some(e=>e.breaker));const e=s.enemies.find(e=>e.breaker);damageEnemy(s,e,10000,'player');m01Steps(s,.1);assert.equal(s.over,false);assert.ok(nexusMissionState(s).pending>0);m01Steps(s,4);assert.ok(s.enemies.some(e=>e.defenseBomber));assert.equal(s.over,false);
});
test('M01 2B : plafonds et espacement des bombardiers, pas de saturation',()=>{
 for(const difficulty of ['easy','normal','hard']){const s=m01Run(difficulty);m01Until(s,s=>nexusMissionState(s).phase===2,40,true);let max=0,lastSpawn=-100,ids=new Set();for(let i=0;i<100*120&&!s.over;i++){
  updateNexusMission(s,1/120);assert.ok(s.enemies.length<=M01_LIMITS.enemies);assert.ok(s.nexus.state.activeBombers<=M01_LIMITS.bombers);const bombers=s.enemies.filter(e=>e.defenseBomber);max=Math.max(max,bombers.length);
  for(const e of bombers)if(!ids.has(e.id)){assert.ok(s.t-lastSpawn>=M01_PLAN[difficulty][nexusMissionState(s).phase-2].interval-.01);lastSpawn=s.t;ids.add(e.id);}
  if(bombers.length===2)assert.ok(Math.abs(bombers[0].x-bombers[1].x)>=s.width*.2-1e-6);
 }assert.ok(max>0);
 }
});
test('M01 2B : passages réels, dégâts uniques et Nexus à zéro ferme le contrôleur',()=>{
 const s=m01Run('hard');m01Until(s,s=>nexusMissionState(s).phase===2,40,true);m01Until(s,s=>s.over,180);assert.equal(nexusMissionState(s).outcome.reason,'defeat_nexus');assert.equal(s.nexus.state.integrity,0);assert.equal(s.victory,false);const end=nexusMissionState(s);m01Steps(s,20);assert.deepEqual(nexusMissionState(s),end);assert.deepEqual([s.enemies.length,s.hostile.length,s.bullets.length,s.events.length,s.effects.length,s.particles.length],[0,0,0,0,0,0]);
});
test('M01 2B : défaite pilote et priorité déterministe si double destruction',()=>{
 for(const both of [false,true]){const s=m01Run();s.hp=0;if(both)for(let i=0;i<5;i++){s.nexus.register(500+i,'heavy');s.nexus.crossing(500+i);}updateNexusMission(s,1/120);assert.equal(nexusMissionState(s).outcome.reason,both?'defeat_nexus':'defeat_player');assert.equal(s.victory,false);assert.ok(s.nexus.state.closed);}
});
test('M01 2B : victoire logique seulement après les derniers bombardiers et leurs tirs',()=>{
 const s=m01Run();m01Until(s,s=>nexusMissionState(s).phase===3,100,true);m01Until(s,s=>nexusMissionState(s).pending===0,100,true);assert.equal(s.over,false);s.hostile.push({x:10,y:10,vx:0,vy:0,r:1,damage:0,life:2,arm:0});m01Steps(s,.5,true);assert.equal(s.over,false);m01Until(s,s=>s.over,10,true);assert.equal(nexusMissionState(s).outcome.reason,'objectives_met');assert.equal(s.victory,false);
});
test('M01 2B : redimensionnement garde l’avancement et ne résout aucune menace',()=>{
 const s=m01Run();m01Until(s,s=>nexusMissionState(s).phase===2,40,true);m01Until(s,s=>s.enemies.some(e=>e.defenseBomber));const e=s.enemies.find(e=>e.defenseBomber),p=e.defenseBomber.progress,m=nexusMissionState(s);for(const [w,h] of [[1152,720],[480,1066],[480,1038]]){setDefenseBounds(s,w,h);assert.equal(e.defenseBomber.progress,p);assert.deepEqual(nexusMissionState(s),m);assert.equal(s.nexus.state.integrity,100);}
});
test('M01 2B : pause, arrière-plan et reprise explicite figent contrôleur et défense',async()=>{
 const session=createNexusMissionSession(),s=await session.start({ship:'revenant',weapon:'flux',drone:'alpha',difficulty:'normal'});session.step(.1,{},true,true);assert.equal(session.pause(),true);const state=nexusMissionState(s),t=s.t;session.step(.2,{},true,true);updateNexusMission(s,.2);assert.equal(s.t,t);assert.deepEqual(nexusMissionState(s),state);assert.equal(session.resume(),true);session.step(.1,{},true,false);assert.equal(s.t,t);session.step(.1,{},false,true);assert.equal(s.t,t);session.step(.1,{},true,true);assert.ok(s.t>t);assert.equal(session.takeResult(),null);
});
test('M01 2B : abandon nettoie, annule le lancement et nouveau départ remet NOVA et Nexus à zéro/100',async()=>{
 const session=createNexusMissionSession(),s=await session.start({ship:'revenant',weapon:'flux',drone:'alpha',difficulty:'normal'});s.novaCharge=100;session.step(.1,{},true,true);session.abandon();assert.equal(session.run,null);assert.equal(nexusMissionState(s).outcome.reason,'abandoned');assert.ok(s.nexus.state.closed);assert.equal(s.enemies.length+s.bullets.length+s.hostile.length+s.events.length,0);let release;const pending=session.start({ship:'wisp',weapon:'missile',drone:'beta'},()=>new Promise(r=>release=r));session.cancelStart();release();assert.equal(await pending,null);const next=await session.start({ship:'bastion',weapon:'impact',drone:'beta',difficulty:'easy'});assert.equal(next.novaCharge,0);assert.equal(next.nexus.state.integrity,100);assert.equal(nexusMissionState(next).phase,1);session.end();assert.equal(session.takeResult(),null);
});
test('M01 2B : résultat unique, immuable par les appels ultérieurs et jamais distribuable',async()=>{
 const session=createNexusMissionSession(),s=await session.start({ship:'revenant',weapon:'flux',drone:'none',difficulty:'normal'});s.hp=10000;s.shot=10000;m01Until(s,s=>s.over,180,true);const before=nexusMissionState(s);for(let i=0;i<5;i++){session.step(.1,{},true,true);session.end();assert.equal(session.takeResult(),null);assert.deepEqual(nexusMissionState(s),before);}
});
test('M01 2B : contrôleur sans stockage, disponibilité publique raccordée par le lot 3',async()=>{
 const source=await readFile(new URL('../src/campaign/nexus-m01.js',import.meta.url),'utf8');assert.doesNotMatch(source,/recordMissionVictory|applyCampaignVictory|localStorage|credits|bestStars/);const catalog=await import('../src/campaign/catalog.js');assert.equal(catalog.MISSIONS.find(m=>m.id==='nexus_m01').playable,true);assert.equal(catalog.MISSIONS.find(m=>m.id==='nexus_m01').status,'available');
});
test('M01 2B : deltas invalides ignorés et sous-pas reproductibles',()=>{
 const a=m01Run(),b=m01Run();for(const dt of [NaN,Infinity,0,-1,.201])updateNexusMission(a,dt);assert.equal(a.t,0);updateNexusMission(a,.1);for(let i=0;i<12;i++)updateNexusMission(b,1/120);assert.equal(a.t,b.t);assert.deepEqual(nexusMissionState(a),nexusMissionState(b));
});

test('M01 2B : salve du Briseur évitable après signal court avec chaque châssis et difficulté',()=>{
 for(const [width,height] of [[1152,720],[480,1038],[480,1066]])for(const difficulty of ['easy','normal','hard'])for(const ship of ['revenant','wisp','bastion']){
  let safe=false;
  for(const [dx,duration] of [-1,1,0].flatMap(dx=>[.45,.7,1,1.5,7].map(duration=>[dx,duration]))){const s=createRun({ship,weapon:'flux',drone:'none',difficulty});setBounds(s,width,height);s.shot=1000;s.x=width/2;s.y=height*.85;
   const e=createEnemy(s,'heavy',{breaker:true,hp:BREAKER.hp,maxHp:BREAKER.hp,r:BREAKER.r,size:BREAKER.size,center:width/2,x:width/2,y:155,age:6,cooldown:0});s.enemies=[e];let visible=null;
   const scenario={handles:()=>false,move:updateEnemies,snapshot(){},resolve(){}};
   for(let i=0;i<7*120;i++){if(e.warning&&(difficulty==='easy'||e.warning.time<=.3)&&visible===null)visible=s.t;if(s.stats.volleys)e.cooldown=1000;update(s,1/120,{dx:visible!==null&&s.t-visible>=.15&&s.t-visible<.15+duration?dx:0},scenario);}
   if(s.stats.volleys===1&&s.stats.damageTaken===0){safe=true;break;}
  }assert.ok(safe,`${width}x${height}/${difficulty}/${ship}`);
 }
});
test('M01 2B : score transitoire et NOVA conservés, aucun bonus NOVA automatique ou réparation',()=>{
 const s=createNexusMissionRun({ship:'bastion',weapon:'flux',drone:'none',difficulty:'easy'});s.shot=10000;assert.equal(s.novaCharge,0);m01Steps(s,1);const e=s.enemies[0];damageEnemy(s,e,1000,'drone');m01Steps(s,.02);assert.equal(s.novaCharge,12);assert.equal(s.stats.droneKills,1);assert.equal(s.score,100);s.nexus.register(999,'light');s.nexus.crossing(999);s.novaCharge=100;assert.equal(nova(s),true);assert.equal(s.nexus.state.integrity,90);assert.equal(s.novaCharge,0);assert.equal(s.stats.novaUses,1);
});


test('M01 2B : collision du Briseur affecte le pilote, jamais l’intégrité de Nexus',()=>{
 const s=m01Run();m01Until(s,s=>nexusMissionState(s).phase===3,100,true);m01Until(s,s=>s.enemies.some(e=>e.breaker));const e=s.enemies.find(e=>e.breaker);e.y=155;s.x=e.x;s.y=e.y+e.r+s.spec.r-2;s.invincible=0;const armor=s.hp;updateNexusMission(s,1/120);assert.ok(s.hp<armor);assert.equal(s.nexus.state.integrity,100);assert.equal(s.nexus.state.activeBombers,0);assert.equal(e.defenseBomber,undefined);
});

// Lot 3 : intégration au jeu principal et règlement persistant des victoires confirmées.
import {starsForIntegrity,confirmedMissionResult,createMissionResults} from '../src/campaign/results.js';
import {createFlightSession} from '../src/flight-session.js';
function m01Win(integrity=100,difficulty='normal'){
 const s=m01Run(difficulty);m01Until(s,s=>nexusMissionState(s).phase===3,100,true);
 for(let n=0;n<(100-integrity)/10;n++){s.nexus.register(1000+n,'light');s.nexus.crossing(1000+n);}
 m01Until(s,s=>s.over,100,true);return s;
}
test('Lot 3 : frontières exactes étoiles 0,59,60,89,90,100',()=>{for(const [integrity,stars] of [[0,0],[59,1],[60,2],[89,2],[90,3],[100,3]])assert.equal(starsForIntegrity(integrity),stars);});
