import {readHistorical,validateLegacy as validateHistorical,LEGACY_KEYS} from '../src/persistence/legacy.js';
const legacyFixture=(entries={})=>({getItem:key=>Object.hasOwn(entries,key)?entries[key]:null});
test('Persistence : premier lancement prépare 14 compteurs zéro et trois blindages pleins',()=>{const s=initialPersistenceState(readHistorical(legacyFixture()));assert.equal(s.economy.balance,0);assert.deepEqual(Object.values(s.fleet).map(f=>f.currentHp),[65,100,155]);assert.equal(Object.values(s.upgrades.ships).flatMap(Object.values).concat(Object.values(s.upgrades.weapons),Object.values(s.upgrades.drones)).length,14);assert.ok(Object.values(s.upgrades.ships).flatMap(Object.values).concat(Object.values(s.upgrades.weapons),Object.values(s.upgrades.drones)).every(v=>v===0));assert.deepEqual(s.lastResort,{obtained:false,voucherGranted:false,voucherConsumed:false});assert.ok(Object.values(s.fleet).every(f=>!f.destroyed&&f.reservation===null&&f.rescueDueAt===null));validatePersistenceState(s);});
test('Persistence : crédits, choix, record et sources brutes conservés',()=>{const raw=JSON.stringify({version:1,credits:9876,best:1234,ship:'bastion',weapon:'missile',drone:'beta',opaque:{keep:42}});const s=initialPersistenceState(readHistorical(legacyFixture({nv2_save_v1:raw})));assert.equal(s.economy.balance,9876);assert.equal(s.migration.raw.nv2_save_v1,raw);assert.equal(s.migration.profile.best,1234);assert.equal(s.migration.profile.ship,'bastion');assert.equal(s.migration.profile.weapon,'missile');assert.equal(s.migration.profile.drone,'beta');assert.deepEqual(JSON.parse(s.migration.raw.nv2_save_v1).opaque,{keep:42});});
test('Persistence : sources corrompues et versions futures refusées sans écriture',()=>{for(const key of LEGACY_KEYS)for(const raw of ['BAD','null','[]','{"version":99}'])assert.throws(()=>readHistorical(legacyFixture({[key]:raw})));});
test('Persistence : bornes historiques ambiguës refusées, pas de troncature de crédits',()=>{for(const credits of [-1,1.5,1e9+1,'20',null])assert.throws(()=>validateHistorical('nv2_save_v1',JSON.stringify({version:1,credits,best:0,ship:'revenant',weapon:'flux',drone:'none'})));});
test('Persistence : préférences invalides et IDs de choix inconnus refusés',()=>{for(const value of [{volume:2},{enabled:'yes'},{difficulty:'future'}])assert.throws(()=>validateHistorical('nv2_preferences_v1',JSON.stringify(value)));assert.throws(()=>validateHistorical('nv2_save_v1','{"version":1,"ship":"future"}'));});
test('Persistence : état futur, économie corrompue et niveaux hors bornes refusés',()=>{const base=initialPersistenceState(readHistorical(legacyFixture()));for(const mutate of [s=>s.version=2,s=>s.minWriter=2,s=>s.economy.balance=-1,s=>s.economy.balance=1e9+1,s=>s.upgrades.weapons.flux=6,s=>s.upgrades.drones.alpha=.5,s=>s.upgrades.ships.revenant.nova=-1,s=>s.revision=Infinity]){const s=structuredClone(base);mutate(s);assert.throws(()=>validatePersistenceState(s));}});
test('Persistence : flotte et bon incohérents refusés',()=>{const base=initialPersistenceState(readHistorical(legacyFixture()));for(const mutate of [s=>s.fleet.revenant.currentHp=0,s=>s.fleet.bastion.destroyed=true,s=>s.fleet.wisp.currentHp=66,s=>s.fleet.wisp.rescueDueAt=-1,s=>s.lastResort.voucherConsumed=true]){const s=structuredClone(base);mutate(s);assert.throws(()=>validatePersistenceState(s));}});
test('Persistence : schéma conserve les extensions compatibles sans les appliquer',()=>{const s=initialPersistenceState(readHistorical(legacyFixture()));s.opaque={keep:42};assert.equal(validatePersistenceState(s),s);assert.deepEqual(s.opaque,{keep:42});});
test('Persistence : aucun producteur de portefeuille importé par le jeu',async()=>{const fs=await import('node:fs/promises');for(const file of ['main.js','garage.js','combat.js','campaign/results.js'])assert.doesNotMatch(await fs.readFile(new URL('../src/'+file,import.meta.url),'utf8'),/persistence\/wallet|\.reward\(|\.purchase\(|\.repair\(/);});

test('Persistence : sauvegardes partielles ambiguës bloquées au lieu de créer un portefeuille vide',()=>{assert.throws(()=>readHistorical(legacyFixture({nv2_save_v1:'{"version":1,"credits":1234}'})),/legacy-ambiguous/);assert.throws(()=>readHistorical(legacyFixture({nv2_preferences_v1:'{}'})),/legacy-ambiguous/);});
